-- 4. Discovery Phase_ Стратегическое проектирование как фундамент прибыльного IT-продукта
INSERT INTO pages (slug, published, publish_at, image, tags, translations)
VALUES ('discovery-phase', FALSE, NULL, '/uploads/pages/discovery-phase/cat-discovery.png', ARRAY['Discovery', 'Architecture', 'MVP'], $page_2${"en": {"title": "Discovery Phase: Strategic IT Product Design Before Code", "description": "Discovery Phase in software: pre-project analytics, architecture, wireframes, estimate and roadmap. Cut budget and timeline risk before coding starts.", "body": "Most IT projects exceed budget by 50–100% or shut down within a year of launch. The root cause is rarely \"bad developers\" — it is building without design. Development without Discovery is like erecting a skyscraper without blueprints: money drains away, deadlines slip, and the product misses the market. Discovery Phase turns an idea into a validated specification with clear economics — before you spend the main development budget.\n\n## Anatomy of Discovery Phase at Piplos Media\n\nDiscovery is not \"draw mockups in a week.\" It is a structured process that links business goals, user scenarios, and technical feasibility into one actionable plan.\n\n**1. Business analysis.** We define product goals, KPIs, constraints, and success criteria. If a metric is undefined, it cannot be built into architecture or prioritised in the backlog.\n\n**2. User research.** We identify user segments, jobs to be done, and usage context. User Stories and Job Stories describe concrete flows with acceptance criteria — not a vague \"user dashboard.\"\n\n**3. Technical audit and architecture.** Stack choices are evidence-based: Go for high-load APIs, Flutter for cross-platform clients, PostgreSQL or ClickHouse depending on data patterns. We document integrations and Non-functional requirements (NFR): load, SLA, security, scaling. High-level Architecture sets service boundaries before the first line of code.\n\n**4. Prototyping.** Interactive wireframes validate hypotheses with stakeholders and future users. A prototype costs orders of magnitude less than rewriting production code.\n\nThe output is a technical specification you can build from — not a slide deck for sign-off. Architecture work connects to our [backend expertise](/en/services/backend): we design systems we are prepared to implement.\n\n## Discovery economics: stage ROI\n\nChanging business logic during analytics costs roughly $100. The same change after code is written and integrated — $5,000 and up: API rework, data migrations, regression testing, release delays.\n\nDiscovery surfaces \"impossible\" features before development starts: integrations with no public API, latency requirements that conflict with the data model, MVP features with zero ROI. That is not pessimism — it is risk mitigation.\n\n**TCO (Total Cost of Ownership).** Sound architecture upfront lowers maintenance cost for years: fewer workarounds, clear module boundaries, documented NFR. Saving on Discovery means overpaying on every sprint that follows.\n\n## Why \"free estimates in 15 minutes\" cannot be trusted\n\nAgencies that quote a range after one call are not analysing your product — they are selling a template. Without Discovery, estimates are guesswork: hidden integrations, uncounted edge cases, and \"we assumed the API existed\" surface on sprint three.\n\nAn accurate estimate and realistic roadmap are only possible after pre-project analytics. That is the honest approach: you know scope, risks, and cost before signing a development contract. We do not sell Discovery as a margin add-on — it is the only way to keep development from becoming a black box with an unpredictable invoice.\n\n## Deliverables: what you receive\n\n- **PRD (Product Requirements Document)** — goals, User Stories, priorities, explicit out of scope;\n- **Architecture diagram** — services, integrations, data flows, NFR;\n- **Wireframes / prototypes** — key screens and flows for team alignment;\n- **Detailed estimate** — breakdown by phase and module, not a vague range;\n- **Development roadmap** — phases, MVP scope, dependencies, decision points.\n\nDocuments remain yours whether you continue with us or an in-house team.\n\n## Frequently asked questions\n\n### How long does Discovery Phase take?\n\nTypically 2–6 weeks — depending on product complexity, number of integrations, and readiness of business requirements. A narrow MVP scope is faster; an enterprise platform with multiple roles and external systems takes longer — but still costs a fraction of post-launch rework.\n\n### Can we skip Discovery and start coding immediately?\n\nYou can — if you accept budget ×1.5–2 and timelines ×2. In practice, \"fast start without analytics\" means Discovery happens inside development — at full sprint cost and team burn rate.\n\n### Is Discovery only for startups?\n\nNo. Enterprise Product Owners, teams before a major rewrite, and investors before a funding round use Discovery for technical due diligence: a clear backlog, justified stack, transparent estimate.\n\nDiscovery is not an expense — it is an investment with immediate payback: you pay for clarity before a mistake becomes expensive. Book an intro session with our business analyst and tech lead: [discuss Discovery for your product](/en/order)."}, "ru": {"title": "Discovery Phase: проектирование IT-продукта до разработки", "description": "Discovery Phase в разработке ПО: предпроектная аналитика, архитектура, wireframes, смета и roadmap. Снижаем риски бюджета и сроков до написания кода.", "body": "Большинство IT-проектов выходят за рамки бюджета на 50–100% или закрываются в первый год после запуска. Главная причина — не «плохие разработчики», а отсутствие проектирования до старта кодинга. Разработка без Discovery — это строительство небоскрёба без чертежей: деньги уходят, сроки срываются, а продукт не решает задачу рынка. Discovery Phase превращает идею в проверенную спецификацию с понятной экономикой — до того, как вы потратите основной бюджет на разработку.\n\n## Анатомия Discovery Phase в Piplos Media\n\nDiscovery — не «нарисовать макеты за неделю». Это структурированный процесс, который связывает бизнес-цели, пользовательские сценарии и техническую реализуемость в единый план.\n\n**1. Бизнес-анализ.** Фиксируем цели продукта, KPI, ограничения и критерии успеха. Если метрика не определена — её невозможно заложить в архитектуру и приоритизировать в backlog.\n\n**2. User Research.** Определяем сегменты пользователей, их задачи и контекст использования. Формируем User Stories и Job Stories — не абстрактный «личный кабинет», а конкретные сценарии с acceptance criteria.\n\n**3. Технический аудит и архитектура.** Выбираем стек обоснованно: Go для высоконагруженного API, Flutter для кроссплатформенного клиента, PostgreSQL или ClickHouse — в зависимости от паттерна данных. Описываем интеграции, Non-functional requirements (NFR): нагрузка, SLA, безопасность, масштабирование. High-level Architecture фиксирует границы сервисов до первой строки кода.\n\n**4. Прототипирование.** Создаём интерактивные wireframes для проверки гипотез с stakeholders и будущими пользователями. Прототип дешевле переделки production-кода в три порядка.\n\nИтог Discovery — техническая спецификация, по которой можно строить проект, а не презентация «на согласование». Архитектурная часть пересекается с нашей [backend-экспертизой](/ru/services/backend): мы проектируем системы, которые потом реализуем сами.\n\n## Экономика Discovery: ROI этапа\n\nИзменение бизнес-логики на этапе аналитики стоит условно $100. То же изменение после написания и интеграции кода — $5000 и выше: переделка API, миграции данных, регрессионное тестирование, срыв релиза.\n\nDiscovery выявляет «невозможные» функции до старта разработки: интеграции без публичного API, требования к latency, которые противоречат выбранной модели данных, функции с нулевым ROI для MVP. Если проблема → последствие → решение через Discovery — цепочка становится прозрачной для всей команды, включая инвесторов. Это не пессимизм — это risk mitigation.\n\n**TCO (Total Cost of Ownership).** Правильная архитектура на старте снижает стоимость поддержки на годы вперёд: меньше костылей, понятные границы модулей, документированные NFR. Экономия на Discovery оборачивается переплатой за каждый последующий спринт.\n\n## Почему нельзя доверять «бесплатным оценкам» за 15 минут\n\nСтудии, которые за один созвон называют «вилку от $X до $Y», не анализируют ваш продукт — они продают шаблон. Без Discovery оценка — это guesswork: скрытые интеграции, неучтённые edge cases и «мы думали, что API есть» всплывают на третьем спринте.\n\nТочная смета и реалистичный roadmap возможны только после предпроектной аналитики. Это честный подход: вы знаете scope, риски и стоимость до подписания контракта на разработку. Мы не продаём Discovery как «доп. услугу ради маржи» — это единственный способ не превратить разработку в чёрный ящик с непредсказуемым счётом.\n\n## Результаты этапа: что вы получаете\n\n- **PRD (Product Requirements Document)** — цели, User Stories, приоритеты, out of scope;\n- **Архитектурная схема** — сервисы, интеграции, потоки данных, NFR;\n- **Wireframes / прототипы** — ключевые экраны и сценарии для согласования с командой;\n- **Детальная смета** — breakdown по этапам и модулям, а не «от и до»;\n- **Roadmap разработки** — фазы, MVP scope, зависимости, точки принятия решений.\n\nДокументы остаются у вас независимо от того, продолжите ли разработку с нами или со своей in-house командой — это ваш актив, а не «артефакт ради отчёта».\n\n## Частые вопросы\n\n### Сколько длится Discovery Phase?\n\nОбычно от 2 до 6 недель — в зависимости от сложности продукта, числа интеграций и готовности бизнес-требований. MVP с узким scope быстрее; enterprise-платформа с несколькими ролями и внешними системами — дольше, но всё равно кратно дешевле переделки после запуска.\n\n### Можно ли пропустить Discovery и сразу писать код?\n\nМожно — если вы готовы к бюджету ×1.5–2 и срокам ×2. На практике «быстрый старт без аналитики» означает, что Discovery случится уже в разработке — но за полную стоимость спринтов и с burning rate команды.\n\n### Discovery подходит только для стартапов?\n\nНет. Product Owners enterprise-продуктов, команды перед major rewrite и инвесторы перед раундом используют Discovery для технического due diligence: понятный backlog, обоснованный стек, прозрачная смета.\n\nDiscovery — не трата, а инвестиция с быстрой окупаемостью: вы платите за ясность до того, как ошибка станет дорогой. Запишитесь на вводную консультацию с бизнес-аналитиком и техлидом: [обсудить Discovery для вашего продукта](/ru/order)."}}$page_2$)
ON CONFLICT (slug) DO UPDATE SET
  published = EXCLUDED.published,
  publish_at = EXCLUDED.publish_at,
  image = EXCLUDED.image,
  tags = EXCLUDED.tags,
  translations = EXCLUDED.translations,
  updated_at = now();

INSERT INTO seo_pages (path, translations)
VALUES ('/articles/discovery-phase', $seo_2${"en": {"title": "Discovery Phase: Strategic IT Product Design Before Code", "description": "Discovery Phase in software: pre-project analytics, architecture, wireframes, estimate and roadmap. Cut budget and timeline risk before coding starts.", "keywords": "Discovery Phase software development, pre-project analytics, software requirements gathering, application architecture design, software development cost estimate, MVP Discovery, User Stories, NFR, wireframes, TCO, risk mitigation", "og_title": "Discovery Phase: Design Your Product Before Code", "og_description": "Pre-project analytics, architecture, wireframes and a detailed estimate. Reduce budget risk before development starts. Consult with our analyst and tech lead.", "og_image": "/uploads/pages/discovery-phase/cat-discovery.png"}, "ru": {"title": "Discovery Phase: проектирование IT-продукта до разработки", "description": "Discovery Phase в разработке ПО: предпроектная аналитика, архитектура, wireframes, смета и roadmap. Снижаем риски бюджета и сроков до написания кода.", "keywords": "Discovery Phase в разработке ПО, дискавери фаза, предпроектная аналитика, сбор требований к ПО, проектирование архитектуры приложения, оценка стоимости разработки, MVP Discovery, User Stories, NFR, wireframes, TCO, risk mitigation", "og_title": "Discovery Phase: спроектируйте продукт до кода", "og_description": "Предпроектная аналитика, архитектура, wireframes и детальная смета. Снижаем риски бюджета до старта разработки. Консультация с аналитиком и техлидом.", "og_image": "/uploads/pages/discovery-phase/cat-discovery.png"}}$seo_2$)
ON CONFLICT (path) DO UPDATE SET
  translations = EXCLUDED.translations,
