VALUES ('/articles/generative-ui-design', $seo_4${"en": {"title": "Generative UI: How AI Is Reshaping UX/UI Design in 2026", "description": "AI in UI/UX design: Generative UI, hyper-personalization, and Intent-based UI. 2026 UX trends and adaptive product design from Piplos Media.", "keywords": "AI in UI/UX design, web design trends 2026, generative design, AI interface personalization, adaptive systems design, future of UX/UI, Generative UI, Dynamic layouts, Hyper-personalization, Zero UI, LLM, AI-driven prototyping, Accessibility", "og_title": "Generative UI: AI-Powered Interface Design by Piplos Media", "og_description": "Hyper-personalization, Intent-based UI, and 2026 trends. We design intelligent interfaces for web and mobile. End-to-end concept design.", "og_image": "/uploads/pages/generative-ui-design/cat-generative-ui.png"}, "ru": {"title": "Generative UI: как ИИ меняет UX/UI дизайн в 2026", "description": "ИИ в дизайне интерфейсов: Generative UI, гипер-персонализация и Intent-based UI. Тренды UX/UI 2026 и адаптивные продукты от Piplos Media.", "keywords": "ИИ в дизайне интерфейсов, тренды веб-дизайна 2026, генеративный дизайн, персонализация интерфейса через ИИ, проектирование адаптивных систем, будущее UX/UI, Generative UI, Dynamic layouts, Hyper-personalization, Zero UI, LLM, AI-driven prototyping, Accessibility", "og_title": "Generative UI: дизайн интерфейсов с ИИ от Piplos Media", "og_description": "Гипер-персонализация, Intent-based UI и тренды 2026. Проектируем интеллектуальные интерфейсы для веба и мобайла. Концепт-дизайн под ключ.", "og_image": "/uploads/pages/generative-ui-design/cat-generative-ui.png"}}$seo_4$)
